const input = $json.body ?? $json;
const required = ['customer_id', 'amount', 'currency'];
const missing = required.filter(f => input[f] === undefined || input[f] === null || input[f] === '');
if (missing.length) return [{json: {valid:false,error:'Missing required fields',missing_fields:missing}}];
const amount = Number(input.amount);
if (!Number.isFinite(amount) || amount <= 0) return [{json:{valid:false,error:'Invalid transaction amount'}}];
const currency = String(input.currency).trim().toUpperCase();
if (!/^[A-Z]{3}$/.test(currency)) return [{json:{valid:false,error:'Invalid currency'}}];
return [{json:{valid:true,customer_id:String(input.customer_id).trim(),amount:Number(amount.toFixed(2)),currency,
merchant_id:input.merchant_id?String(input.merchant_id).trim():null,
payment_method:input.payment_method?String(input.payment_method).trim().toLowerCase():null,
country:input.country?String(input.country).trim().toUpperCase():null,
ip_address:input.ip_address?String(input.ip_address).trim():null,
transaction_timestamp:input.transaction_timestamp?new Date(input.transaction_timestamp).toISOString():new Date().toISOString()}}];

const crypto = require('crypto');
const data = $json;
const transactionId = `TXN-${Date.now()}-${crypto.randomBytes(4).toString('hex').toUpperCase()}`;
const fingerprintSource = [data.customer_id,data.amount.toFixed(2),data.currency,data.merchant_id ?? '',data.payment_method ?? '',data.transaction_timestamp].join('|');
const transactionFingerprint = crypto.createHash('sha256').update(fingerprintSource).digest('hex');
return [{json:{...data,transaction_id:transactionId,transaction_fingerprint:transactionFingerprint}}];

const tx = $('Generate Transaction ID').first().json;
const duplicateRows = $('PostgreSQL - Check Duplicate').all();
const history = $('PostgreSQL - Customer History').all();
const duplicate = duplicateRows.length > 0;
const transactions = history.map(i => i.json);
const totalPrevious = transactions.length;
const totalPreviousAmount = transactions.reduce((sum,t) => sum + Number(t.amount || 0),0);
const averageAmount = totalPrevious ? totalPreviousAmount / totalPrevious : 0;
const amountDeviation = averageAmount > 0 ? Number(tx.amount) / averageAmount : null;
const flags = [];
if (duplicate) flags.push('DUPLICATE_TRANSACTION');
if (Number(tx.amount) >= 50000) flags.push('HIGH_VALUE_TRANSACTION');
if (amountDeviation !== null && amountDeviation >= 5) flags.push('AMOUNT_MUCH_HIGHER_THAN_HISTORY');
if (tx.country && tx.country !== 'PH') flags.push('FOREIGN_COUNTRY');
return [{json:{...tx,duplicate,customer_history_count:totalPrevious,customer_average_amount:Number(averageAmount.toFixed(2)),amount_deviation:amountDeviation !== null ? Number(amountDeviation.toFixed(2)) : null,rule_flags:flags,customer_history:transactions}}];

const data = $json;
const score = Number(data.ai_risk_score || 0);
const duplicate = Boolean(data.duplicate);
const flags = Array.isArray(data.rule_flags) ? data.rule_flags : [];
let finalStatus, decision, reason;
if (duplicate) { finalStatus='HOLD'; decision='BLOCK_DUPLICATE'; reason='Duplicate transaction detected'; }
else if (flags.includes('HIGH_VALUE_TRANSACTION') && score >= 70) { finalStatus='HOLD'; decision='BLOCK_HIGH_RISK'; reason='High-value transaction with high AI risk score'; }
else if (score >= 70) { finalStatus='HOLD'; decision='BLOCK_HIGH_RISK'; reason='Transaction exceeded high-risk threshold'; }
else if (score >= 30) { finalStatus='MANUAL_REVIEW'; decision='REVIEW'; reason='Transaction requires manual review'; }
else { finalStatus='APPROVED'; decision='ALLOW'; reason='Transaction passed automated risk checks'; }
return [{json:{...data,final_status:finalStatus,decision,decision_reason:reason,processed_at:new Date().toISOString()}}];

